/* DALI status query response bitmask values - See DALI Standard
 IEC 62386-102 control-GEAR status byte (reply to the 16-bit QUERY STATUS, for lamps/drivers).
 NOTE: this is NOT the IEC 62386-103 control-DEVICE deviceStatus (reply to the 24-bit QUERY DEVICE STATUS
 used for input devices/sensors). For a SENSOR power cycle, powerCycleSeen is deviceStatus bit5 (0x20), not
 the bit7 (=128) below. */
typedef enum _DALIStatusType {
    DALIStatusType_LAMP_OFF = 0, /* Not technically in DALI. But this is the default when mask = 0b00000000 */
    DALIStatusType_CONTROL_GEAR_FAILURE = 1, /* Bit 0: control gear failure */
    DALIStatusType_LAMP_FAILURE = 2, /* Bit 1: lamp failure */
    DALIStatusType_LAMP_ON = 4, /* Bit 2: lamp on (arc power above 0) */
    DALIStatusType_LIMIT_ERROR = 8, /* Bit 3: limit error - the last level asked for was outside min / max */
    DALIStatusType_FADE_RUNNING = 16, /* Bit 4: a fade is running */
    DALIStatusType_RESET_STATE = 32, /* Bit 5: in the reset state */
    DALIStatusType_SHORT_ADDRESS = 64, /* Bit 6: short address is MASK (no short address) */
    DALIStatusType_POWER_CYCLE_SEEN = 128 /* Bit 7: power cycle seen since the last reset */
} DALIStatusType;

/* DALI Receive Flag */
typedef enum _DALIRXStatusFlag {
    DALIRXStatusFlag_WAITING = 0, /* Internal Idle State - Should not be received */
    DALIRXStatusFlag_RECEIVING_FRAME = 1, /* DALI Frame being Received */
    DALIRXStatusFlag_NO_RECEIVED_FRAME = 2, /* Frame was recorded - Empty Data */
    DALIRXStatusFlag_RECEIVED_8_BIT_FRAME = 3, /* Frame was recorded - 8 Bit Reply */
    DALIRXStatusFlag_RECEIVED_16_BIT_FRAME = 4, /* Frame was recorded - 16 Bit - Standard Message */
    DALIRXStatusFlag_RECEIVED_24_BIT_FRAME = 5, /* Frame was recorded - 24 Bit - eDALI Message */
    DALIRXStatusFlag_RECEIVED_PARTIAL_FRAME = 6, /* Frame was recorded - Unusual Bit count */
    DALIRXStatusFlag_IDLE = 7, /* DALI System Idle */
    DALIRXStatusFlag_CALIBRATION = 8, /* Inhouse DALI Calibration */
    DALIRXStatusFlag_ERROR_WHILE_SENDING = 254, /* Error while trying to Transmit DALI - Possibly no Bus Power */
    DALIRXStatusFlag_ERROR_WHILE_RECEIVING = 255 /* Error while trying to Receive - Invalid Frame Data, or no response */
} DALIRXStatusFlag;

/* Which report a diag_message asks for. Each value says what comes back. */
typedef enum _DiagnosticMessageType {
    DiagnosticMessageType_DIAGNOSTIC_SYSTEM_INFO = 0, /* Can be used to retrieve a large number of properties that describe the capabilities of the device. (Number of supported Lists, Alarms, etc.). Reply: diag_system. Devices: eDIDIO, ADDICT. */
    DiagnosticMessageType_DIAGNOSTIC_INPUT_STATUS = 1, /* Not currently supported (will default to SYSTEM_INFO). Reply: diag_system. Devices: eDIDIO, ADDICT. */
    DiagnosticMessageType_DALI_LEVEL_CACHE = 2, /* Can be used to retrieve the current entries of the in-memory DALI values cache. Reply: level_cache_response (64 levels of line). */
    DiagnosticMessageType_DMX_LEVEL_CACHE = 3, /* Can be used to retrieve the current entries of the in-memory DMX levels cache. Results must be paginated due to size of DMX universe (512). Reply: level_cache_response (64 levels of line, from page x 64). Devices: eDIDIO, ADDICT. */
    DiagnosticMessageType_ROOM_JOINS = 4, /* Removed: the "Joined Rooms" state no longer exists. Reply: AckMessage (INDEX_OUT_OF_BOUNDS). */
    DiagnosticMessageType_DALI_STATUS_CACHE = 5 /* Can be used to retrieve the current entries of the in-memory DALI status cache. Reply: level_cache_response (64 status bytes of line). */
} DiagnosticMessageType;

/* The steps of a firmware update (FirmwareControlMessage), both directions. */
typedef enum _FirmwareCommandType {
    FirmwareCommandType_FW_READY = 0, /* System Ready for Firmware Message */
    FirmwareCommandType_FW_APPLY = 1, /* Sent to controller to initiate a Firmware update */
    FirmwareCommandType_FW_VERIFY = 2, /* Sent to controller to initiate stored Firmware verification - This will complete the firmware upload mode and unlock normal functionality. */
    FirmwareCommandType_FW_VERIFY_FAILED = 3, /* Received from controller - Issue with stored Firmware */
    FirmwareCommandType_FW_VERIFY_SUCCESS = 4, /* Received from controller - Stored Firmware is Valid */
    FirmwareCommandType_FW_READ = 5, /* Sent to controller to request information for currently stored Firmware */
    FirmwareCommandType_FW_CLONE = 6 /* Command to Clone Main FW to Backup. Using the firmware_is_backup flag will clone Backup to Main */
} FirmwareCommandType;

/* How a sequence moves from one colour to the next. */
typedef enum _SpektraTransitionType {
    SpektraTransitionType_BLEND = 0, /* Blended colour transitions. Example: Transition between red and green will go through yellow. */
    SpektraTransitionType_SNAP = 1, /* Instant colour transitions. */
    SpektraTransitionType_FADE_TO_BLACK = 2 /* Example: Transition between red and green will fade the light off then on between colours. Not currently supported. */
} SpektraTransitionType;

/* Types of conditions that can be evaluated in Logic rules */
typedef enum _LogicType {
    LogicType_DALI_LEVEL = 0, /* Compare against a DALI device's arc level (0-254) */
    LogicType_INPUT_STATE = 1, /* Compare against a physical input's current state (HIGH/LOW) */
    LogicType_LIST_RUNNING = 2, /* Check if a specific List is currently running */
    LogicType_OCCUPANCY_DETECTED = 3, /* Check if a sensor has detected occupancy */
    LogicType_DMX_PRESENT = 4, /* Check if DMX input signal is being received */
    LogicType_CAL_WEEKDAY = 5, /* Compare against current day of week (1=Monday to 7=Sunday) */
    LogicType_CAL_MONTH = 6, /* Compare against current month (1=January to 12=December) */
    LogicType_ALARM_SCHEDULED = 7, /* Check if a specific alarm/schedule is active */
    LogicType_DALI_CACHE_STATUS = 8, /* Checks if any DALI device in the cache has an error status */
    LogicType_HAS_ERROR = 9 /* Check device error flags. target_index is bitmask: [bit0=DALI Poll Error, bit1=DALI Line Error, bit2=Ethernet Link Dropped, bit3=Over Temperature, bit4=OLED Error, bits5-7=Reserved] */
} LogicType;

/* How a logic rule compares its variable with comparison_value. It runs trigger A when the comparison holds, else trigger B. */
typedef enum _LogicComparisonType {
    LogicComparisonType_LESS_THAN = 0, /* A runs if the variable < comparison_value, else B */
    LogicComparisonType_LESS_THAN_OR_EQUALS = 1, /* A runs if the variable <= comparison_value, else B */
    LogicComparisonType_EQUALS = 2, /* A runs if the variable == comparison_value, else B */
    LogicComparisonType_MORE_THAN = 3, /* A runs if the variable > comparison_value, else B */
    LogicComparisonType_MORE_THAN_OR_EQUALS = 4, /* A runs if the variable >= comparison_value, else B */
    LogicComparisonType_NOT_EQUAL = 5, /* A runs if the variable != comparison_value, else B */
    LogicComparisonType_BIT_OR = 6, /* A runs if (variable | comparison_value) is non-zero, else B */
    LogicComparisonType_BIT_AND = 7, /* A runs if (variable & comparison_value) is non-zero - any of the masked bits set - else B */
    LogicComparisonType_BIT_XOR = 8 /* A runs if (variable ^ comparison_value) is non-zero - they differ - else B */
} LogicComparisonType;

/* Which frames the device uses to talk to its DALI sensors. */
typedef enum _DALISensorType {
    DALISensorType_EDALI_25_BIT = 0, /* 25-bit frame type for a vendor-specific pre-configured sensor */
    DALISensorType_DEFAULT_DALI_2 = 1 /* The default 24-bit DALI 2 frames */
} DALISensorType;

/* What a SensorCommandMessage does. */
typedef enum _SensorCommandType {
    SensorCommandType_INITIALISE = 0, /* Applies default settings to all Sensors (broadcast) and resets their detection state */
    SensorCommandType_MUTE = 1, /* Stops a Sensor from sending DALI packets */
    SensorCommandType_UNMUTE = 2, /* Allows a Sensor to send DALI packets */
    SensorCommandType_OVERRIDE = 3, /* Puts a Sensor in 'Override Mode' which prevents it from adjusting the Light Level (until after the occupancy timeout occurs) */
    SensorCommandType_IDENTIFY = 4 /* Starts the 'Identify' behaviour of a Sensor (typically this involves rapid flashing of the status LED for several seconds) */
} SensorCommandType;

/* Categories of events recorded in the system log */
typedef enum _SystemLogType {
    SystemLogType_BOOT = 0, /* Device power-on or reboot event */
    SystemLogType_NET_LINK = 1, /* Ethernet link state change (connected/disconnected) */
    SystemLogType_NTP = 2, /* NTP time synchronization event */
    SystemLogType_TRIGGER = 3, /* Trigger action executed (input, schedule, or external) */
    SystemLogType_SPEKTRA = 4, /* Spektra sequence/theme state change */
    SystemLogType_SCHEDULE = 5, /* Scheduled alarm triggered */
    SystemLogType_USER = 6, /* User changed logging level configuration */
    SystemLogType_CRASH = 7, /* Crash record summary (crash_type, PC, CFSR, LR low-16) */
    SystemLogType_WATCHDOG_RESET = 8, /* Watchdog-triggered reset */
    SystemLogType_CRASH_EXT = 9 /* Extended crash data (SP, watchdog_flags, task_name) */
} SystemLogType;

/* Input event types from DALI-2 (24-bit) input devices */
typedef enum _DALI24InputType {
    DALI24InputType_MOMENTARY_SHORT = 0, /* Short button press (< 250ms) */
    DALI24InputType_MOMENTARY_LONG = 1, /* Long button press (> 650ms) */
    DALI24InputType_LATCHED_LOW = 2, /* Switch transitioned to closed/low state */
    DALI24InputType_LATCHED_HIGH = 3, /* Switch transitioned to open/high state */
    DALI24InputType_POSITIONAL = 4 /* Rotary encoder or slider position value */
} DALI24InputType;

/* State machine for DALI motion sensor occupancy detection */
typedef enum _DALIMotionSensorStates {
    DALIMotionSensorStates_MOTION_IDLE = 0, /* No occupancy detected, lights at idle/off level */
    DALIMotionSensorStates_MOTION_DISABLED = 1, /* Sensor is muted or in deadtime period */
    DALIMotionSensorStates_MOTION_WARNING = 2, /* Occupancy timeout reached, lights dimmed to warning level */
    DALIMotionSensorStates_MOTION_OCCUPANCY = 3 /* Active occupancy detected, lights at occupied level */
} DALIMotionSensorStates;

/* State machine for DALI light level (lux) sensor daylight harvesting */
typedef enum _DALILuxSensorStates {
    DALILuxSensorStates_LUX_DISABLED = 0, /* Daylight harvesting is inactive */
    DALILuxSensorStates_LUX_ENABLED = 1, /* Actively regulating to maintain target lux setpoint */
    DALILuxSensorStates_LUX_DEVIATE = 2 /* Light level has deviated significantly from setpoint */
} DALILuxSensorStates;

/* Refines an ERROR AckMessageType with a specific, machine-readable reason, carried in AckMessage.detail
 (detail stays a uint32 - for SUCCESS / PARTIAL_SUCCESS it keeps its existing meaning, e.g. a line bitmask).
 0 = unspecified so older firmware (detail defaults to 0) gracefully degrades to the generic ack message.
 The CLIENT owns the human-readable strings; this enum is the shared code<->meaning contract so firmware and
 app never drift. Values are allocated in 1000-wide blocks per subsystem - add new reasons to the owning
 block, never renumber (gaps are free). uint32/varint: a value stays 2 wire-bytes up to 16383, and the field
 itself reaches ~4.29e9, so the block scheme is effectively open-ended.
   1-999       general / protocol (cross-cutting)
   1000-1999   sensors
   2000-2999   inputs
   3000-3999   outputs
   4000-4999   lists
   5000-5999   schedules / alarms
   6000-6999   zones
   7000-7999   sequences / themes / colour
   8000-8999   DALI commissioning / addressing
   9000-9999   network / config
   10000-10999 admin
   11000-11999 firmware update / apply */
typedef enum _RejectReason {
    RejectReason_REJECT_UNSPECIFIED = 0, /* No specific reason (older firmware, or a generic reject) */
    RejectReason_GENERAL_REQUIRES_NEWER_FIRMWARE = 1, /* The controller firmware is older than the requested feature needs */
    RejectReason_GENERAL_UNSUPPORTED_ON_VARIANT = 2, /* Not supported on this hardware variant */
    RejectReason_SENSOR_BAD_LINE = 1000, /* V4: a sensor must sit on exactly one valid DALI line */
    RejectReason_SENSOR_ADDRESS_OUT_OF_RANGE = 1001, /* V4: sensor short address must be 0-63 */
    RejectReason_SENSOR_CONTROL_LINE_INVALID = 1002, /* V4: control line mask falls outside the available lines */
    RejectReason_SENSOR_CONTROL_TARGET_INVALID = 1003, /* V4: control group/address is out of range */
    RejectReason_SENSOR_TIMER_OUT_OF_RANGE = 1004, /* V8: a timer value would overflow once stored/scaled */
    RejectReason_SENSOR_LEGACY_GROUPING = 1005, /* V7': non-zero legacy motion_sensors (an OLD client) - update the app */
    RejectReason_SENSOR_LEADER_WITHOUT_GROUP = 1006, /* V9: Leader role set without a cooperation group */
    RejectReason_SENSOR_GROUP_ID_INVALID = 1007, /* V9: cooperation group id is too large */
    RejectReason_SENSOR_HARVEST_NO_CONTROL_LINE = 1008, /* V1: a daylight-harvesting sensor must drive at least one line */
    RejectReason_SENSOR_HARVEST_QUERY_ADDR_INVALID = 1009, /* V1: the harvesting seed query address must be a single 0-63 device */
    RejectReason_SENSOR_HARVEST_NO_SETPOINT = 1010, /* V1: the harvesting setpoint must be greater than 0 */
    RejectReason_SENSOR_GROUP_MIXED_TARGET = 1011, /* V2': ACTIVE members of one group must share the control target */
    RejectReason_SENSOR_DUPLICATE_ADDRESS = 1012, /* V10: another programmed sensor already uses this (short address, DALI line) - one physical sensor's events would drive multiple slots */
    RejectReason_FIRMWARE_APPLY_NO_IMAGE = 11000, /* No firmware image is staged in the target slot */
    RejectReason_FIRMWARE_APPLY_CHECKSUM_FAILED = 11001, /* Staged image failed the XOR checksum verify (corrupt or incomplete upload) */
    RejectReason_FIRMWARE_APPLY_BAD_STRUCTURE = 11002, /* Staged image geometry is not cleanly flashable (bad/misaligned chunk addressing) - would brick on handoff */
    RejectReason_FIRMWARE_APPLY_UNSIGNED = 11003, /* No image signature was present - device rejects as unsigned */
    RejectReason_FIRMWARE_APPLY_SIGNATURE_INVALID = 11004, /* Image signature present but did not verify (wrong key, tampered, or content mismatch) */
    RejectReason_FIRMWARE_APPLY_INCOMPLETE = 11005, /* A staged chunk could not be read back (blank/unreadable page) even after retries - the staged image is incomplete/corrupt in flash, NOT a geometry problem. Re-upload. */
    RejectReason_FIRMWARE_UPLOAD_SLOT_NOT_ERASED = 11006, /* Upload: the target page already held DIFFERENT data (the slot was not cleanly erased) - abort and restart the upload */
    RejectReason_FIRMWARE_UPLOAD_WRITE_FAILED = 11007, /* Upload: the post-write read-back did not match what was sent (flash write did not take) - retry the chunk / upload */
    RejectReason_FIRMWARE_SESSION_BUSY = 11008, /* Another connection already owns the firmware update session (single-owner) - wait for it to finish or disconnect, then retry */
    RejectReason_FIRMWARE_APPLY_NO_CONF_KEY = 11009, /* V3: the image is encrypted but the device has no key to decrypt it - provision the device first */
    RejectReason_FIRMWARE_APPLY_DECRYPT_FAILED = 11010, /* V3: image decryption failed - image not applied */
    RejectReason_FIRMWARE_APPLY_BOOTLOADER_INCOMPATIBLE = 11011 /* The staged image needs a firmware format this device's bootloader cannot decode - provide a compatible image */
} RejectReason;

