/* The result of an SD card operation. */
typedef enum _SdStatusCode {
    SdStatusCode_SD_OK = 0, /* Success */
    SdStatusCode_SD_NOT_MOUNTED = 1, /* No card, or it is not mounted */
    SdStatusCode_SD_FILE_NOT_FOUND = 2, /* No such file */
    SdStatusCode_SD_ACCESS_DENIED = 3, /* Not allowed (e.g. delete, until enabled) */
    SdStatusCode_SD_DISK_FULL = 4, /* The card is full */
    SdStatusCode_SD_IO_ERROR = 5, /* The card returned an error */
    SdStatusCode_SD_INVALID_PATH = 6, /* The path is not valid */
    SdStatusCode_SD_BUSY = 7, /* The card is in use - retry */
    SdStatusCode_SD_TIMEOUT = 8, /* The card did not answer in time */
    SdStatusCode_SD_WRITE_ERROR = 9, /* A write failed */
    /* The volume is mounted but its capacity has never been measured: every
 f_getfree() since the mount failed. Returned by SD_GET_SPACE instead of an
 SD_OK carrying free_bytes = total_bytes = 0, which is indistinguishable
 from a card with nothing left on it. A client seeing this should treat
 free space as unknown, not as zero. */
    SdStatusCode_SD_CAPACITY_UNKNOWN = 10,
    /* The operation was abandoned by the device's own per-operation deadline
 rather than failing on the media. Distinguishes a card that is too slow
 (or a bus that stalled) from one that is returning errors: the request
 may well succeed on a retry, where SD_IO_ERROR usually will not. */
    SdStatusCode_SD_DEADLINE_ABORT = 11
} SdStatusCode;

/* What an SdLogPolicyMessage request does. */
typedef enum _SdLogPolicyOp {
    SdLogPolicyOp_SD_LOG_POLICY_GET = 0, /* Read current policy table */
    SdLogPolicyOp_SD_LOG_POLICY_SET = 1, /* Validate + commit new policy table */
    SdLogPolicyOp_SD_LOG_POLICY_RESET = 2 /* Restore flash factory defaults */
} SdLogPolicyOp;

/* Identifies which field in a SET request failed validation. Returned in
 SdLogPolicyMessage.invalid_field when status != SD_OK. */
typedef enum _SdLogPolicyField {
    SdLogPolicyField_SD_LOG_POLICY_FIELD_NONE = 0, /* No field (the table is valid) */
    SdLogPolicyField_SD_LOG_POLICY_FIELD_CATEGORY = 1, /* category index out of range or missing */
    SdLogPolicyField_SD_LOG_POLICY_FIELD_BUDGET_PERMILLE = 2, /* budget_permille is out of range (0-1000) */
    SdLogPolicyField_SD_LOG_POLICY_FIELD_MAX_FILE_SIZE_KB = 3, /* max_file_size_kb is out of range (32-32768) */
    SdLogPolicyField_SD_LOG_POLICY_FIELD_PRIORITY = 4, /* priority is out of range (0-255) */
    SdLogPolicyField_SD_LOG_POLICY_FIELD_DUPLICATE = 5, /* same category appears twice in a SET */
    SdLogPolicyField_SD_LOG_POLICY_FIELD_COUNT = 6 /* wrong number of entries in a SET */
} SdLogPolicyField;

/* Whether the device has a provisioned identity. */
typedef enum _ProvisionState {
    ProvisionState_PROVISION_STATE_UNPROVISIONED = 0, /* Default: no identity; accepts InstallIdentity */
    ProvisionState_PROVISION_STATE_PROVISIONED = 1 /* Identity in flash; refuses re-provision (Decommission first) */
} ProvisionState;

/* The result of a provisioning request. */
typedef enum _ProvisionResult {
    ProvisionResult_PROVISION_RESULT_OK = 0, /* Success */
    ProvisionResult_PROVISION_RESULT_ERR_PARSE = 1, /* supplied identity failed to parse */
    ProvisionResult_PROVISION_RESULT_ERR_CHAIN = 2, /* certificate chain did not validate */
    ProvisionResult_PROVISION_RESULT_ERR_UID_MISMATCH = 3, /* certificate does not match this device's unique ID */
    ProvisionResult_PROVISION_RESULT_ERR_POP = 4, /* key consistency check failed */
    ProvisionResult_PROVISION_RESULT_ERR_FLASH = 5, /* identity store failed */
    ProvisionResult_PROVISION_RESULT_ERR_ALREADY_DONE = 6 /* already PROVISIONED; Decommission first */
} ProvisionResult;

/* Struct definitions */
/* Sent in Response to another message. */
typedef struct _AckMessage {
    AckMessageType payload; /* Will either indicate 'Success' or a particular Error as specified by "AckMessageType" */
    uint32_t detail; /* Optional context. Interpretation depends on payload type: for PARTIAL_SUCCESS on a DALI multi-line command it is the bitmask of lines that succeeded; for an ERROR payload (e.g. INVALID_PARAMS) it is a RejectReason code naming the specific reason (0 = unspecified); for a SUCCESS ack to a secure login it is the granted clearance level (0=NONE, 1=CONTROL, 2=CONFIG, 3=ADMIN). */
} AckMessage;

/* Contains a payload. Used in multiple message types. Incorrect payload type will result in AckMessage Unexpected Type. */
typedef struct _PayloadMessage {
    pb_size_t which_data;
    union {
        uint32_t uint_data; /* Binary Flags set with 0 (FALSE) and 1 (TRUE) */
        float float_data; /* Decimal values (latitude, longitude, UTC offset, ppm) */
    } data;
    char string_data[256]; /* Every PayloadMessage will contain String data, with optional uint or float data */
} PayloadMessage;

/* Trigger Message Structure. Stores all information for Trigger Type Actions */
typedef struct _TriggerMessage {
    TriggerType type; /* The type of Trigger */
    uint32_t zone; /* Which Zone (Spektra) */
    uint32_t line_mask; /* Which Line(s) to perform this trigger on (if applicable) */
    uint32_t target_index; /* Index to target (context depends on TriggerType) */
    uint32_t value; /* Value for this trigger (if applicable) */
    uint32_t query_index; /* Index to query (if applicable) */
} TriggerMessage;

/* Date/Time Message Structure. Year is 0-99. Month is 1 (Jan) - 12 (Dec), Date is day of the month, Day is Weekday with 1 (Monday) - 7 (Sunday) */
typedef struct _TimeClockMessage {
    uint32_t date; /* Year | Month | Date | Day */
    uint32_t time; /* <Empty> | Hour | Minute | Second */
} TimeClockMessage;

/* "Are You There" Message with some supplementary values for debugging. "Are you there?" messages should be sent within 20 seconds to maintain a connection. However, any received message will reset this timer. */
typedef struct _AytMessage {
    uint32_t timesinceboot; /* Device uptime in seconds */
    float temperature; /* Current Temp on the device internals */
    TimeClockMessage time; /* Current Time of the RTC */
} AytMessage;

/* This message contains the 'variable state' for the Device */
typedef struct _DeviceStateMessage {
    uint32_t uptime; /* Uptime (seconds since boot) */
    float temp; /* Temperature */
    float vbat; /* Battery voltage */
    TimeClockMessage clock; /* RTC Time on device */
    uint32_t next_alarm; /* Index of next alarm */
    TimeClockMessage next_alarm_time; /* Time of next alarm */
    uint32_t input_state; /* Input state mask */
    pb_size_t list_states_count;
    uint8_t list_states[32]; /* State of each List (DISABLED / ENABLED / LOOPING) */
    pb_size_t burn_in_states_count;
    uint8_t burn_in_states[2]; /* State of each Burn-in (RUNNING / NOT RUNNING) */
    pb_size_t sensor_states_count;
    uint8_t sensor_states[40]; /* State of each DALI Sensor (IDLE / DISABLED / WARNING / OCCUPANCY) */
    pb_size_t zone_states_count;
    uint8_t zone_states[10]; /* State of each Spektra Zone (OFF / SEQUENCE / THEME / STATIC) */
    pb_size_t zone_sleep_states_count;
    uint8_t zone_sleep_states[10]; /* Sleep State of each Spektra Zone (TRUE / FALSE) */
    pb_size_t zone_indexes_count;
    uint8_t zone_indexes[10]; /* Index of the selected Sequence, Theme, or Static colour for each Zone */
    uint64_t dali_input_state; /* DALI Input state mask */
    uint32_t output_state; /* Output state mask */
} DeviceStateMessage;

/* Message to describe the two Burn-In objects */
typedef struct _BurnInBitsMessage {
    uint32_t light_state; /* Tracks when a Light is 'On' and "burning in" */
    uint32_t running_flag; /* Whether or not the burn-in is currently counting down */
    uint32_t enable_flag; /* Whether or not the burn-in should count down */
} BurnInBitsMessage;

/* Message to describe the 12 or 24 Physical Inputs. Not sent natively, see InputMultiMessage */
typedef struct _IOInputMessage {
    uint32_t index; /* Which Input is this (0 - 11) on 4 Pole and (0 - 23) on 9 Pole */
    TriggerOperationType button_state; /* How will this Input be triggered? Momentary (short/long press) or Latching (low/high) */
    TriggerMessage short_press; /* What action should occur on short/low */
    TriggerMessage long_press; /* What action should occur on long/high */
} IOInputMessage;

/* Message to describe the 4 or 8 Physical Outputs. Not sent natively, see OutputMultiMessage */
typedef struct _IOOutputMessage {
    uint32_t index; /* Which Output is this? (0 - 3) on 4 Pole and (0 - 7) on 9 Pole. Note: Actual Pin numbers are (9 - 12) and (21 - 24) respectively. */
    uint32_t initial_level; /* Will the Output be Low or High at startup? */
    uint32_t time_trigger_is_active; /* How long should a 'Trigger Output' command last? */
    TriggerOperationType type; /* Is this a continuous (latching) trigger or momentary output? */
} IOOutputMessage;

/* Message to describe the (Up to) 40 DALI 2 Input Devices. Not sent natively, see DALIInputMultiMessage */
typedef struct _DALIInputMessage {
    uint32_t index; /* Which index for this Input */
    uint32_t address; /* The eDALI Address of this Input */
    uint32_t dali_line; /* The DALI Line this Input is on */
    TriggerOperationType button_state; /* How will this Input be triggered? Momentary (short/long press) or Latching (low/high) */
    TriggerMessage short_press; /* What action should occur on short/low */
    TriggerMessage long_press; /* What action should occur on long/high */
    uint32_t instance; /* What instance of the device? If it has multiple inputs */
} DALIInputMessage;

/* Message to describe the Infrared Input (DEPRECATED) */
typedef struct _IOIRMessage {
    uint32_t index; /* IR slot, 0-based */
    TriggerMessage action; /* The trigger the code fires */
    uint32_t codes; /* The IR code to match */
} IOIRMessage;

/* Message to describe the (Up to) 40 DALI 2 Sensors. Not sent natively, see SensorMultiMessage */
typedef struct _SensorMessage {
    uint32_t profile; /* Under which Profile is this Sensor active? */
    uint32_t index; /* The index for this Sensor */
    uint32_t sensor_address; /* The eDALI Address of this Sensor (assumes address of "L" (Light) component with "M" (Motion) at L + 1) */
    uint32_t sensor_dali_line; /* The DALI Line this Sensor is on */
    uint32_t address_query; /* The DALI Address to query for Group-based control */
    uint32_t control_dali_line; /* The DALI Line (mask) to control */
    uint32_t control_group; /* The DALI Group Address to control */
    uint32_t light_setpoint; /* The Lux level to maintain during Daylight Harvesting */
    uint32_t warning_setpoint; /* DEPRECATED (superseded by warning_trigger) - The Arc level to set during the Warning Period */
    uint32_t motion_only; /* Is this Sensor used for motion detection only? If False, Daylight Harvesting will be in effect */
    uint32_t timeout_values; /* Occupancy hold time in MINUTES (firmware multiplies by 60 internally) - duration after last motion detection before entering Warning Period */
    uint32_t warning_values; /* Warning period duration in seconds - time spent in dimmed state before transitioning to Idle/Off */
    uint32_t disable_values; /* Deadtime period in seconds - delay after timeout before the Sensor resumes motion detection */
    uint32_t input_1_pm; /* DEPRECATED - The first Input button used for Two-Button Programming */
    uint32_t input_2_pm; /* DEPRECATED - The second Input button used for Two-Button Programming */
    uint32_t sensor_states; /* DEPRECATED (firmware-internal, not configuration) - Used to keep track of the Motion Sensor state */
    uint32_t motion_sensors; /* DEPRECATED since FW 1.3.0 (Phase 3): legacy 32-bit grouping bitmask. New firmware REJECTS a non-zero value here with INVALID_PARAMS - re-push from an updated SpektraPlus. See coop_group/coop_leader. */
    uint32_t lux_sensors; /* DEPRECATED (firmware-internal, not configuration) - Used to keep track of the Light (Lux) Sensor state */
    uint32_t off_flag; /* DEPRECATED (firmware-internal, not configuration) - Used to keep track of the Control Group's state */
    bool is_programmed; /* Set to 'True' when the Firmware receives a SensorMessage with this Index */
    TriggerMessage detection_trigger; /* The action to perform upon initial detection */
    TriggerMessage warning_trigger; /* The action to perform upon transitioning to the Warning Period */
    TriggerMessage idle_trigger; /* The action to perform upon transitioning to the Idle (disable) Period */
    uint32_t coop_group; /* Cooperative directional group ID (1..0x7FFFFFFF; 0 = standalone). Replaces motion_sensors. Members of the same non-zero group cooperate; Leader members propagate occupancy & share lux. */
    uint32_t coop_leader; /* 1 = Leader member (its motion keeps the group on; shares the daylight-harvest mean with other Leader members). 0 = Follower (kept on by Leader members; fires its own triggers; harvests its own zone). */
} SensorMessage;

/* Message to Query running sensor data */
typedef struct _SensorQuery {
    uint32_t timer; /* Time Remaining in seconds */
    uint32_t light_state; /* Light Group State */
    uint32_t motion_sensor_state; /* Motion Sensor State */
    uint32_t lux_sensor_state; /* Lux Sensor State */
    uint32_t last_lux; /* Last reported lux (sensor device-relative units, not absolute lux) */
    uint32_t last_commanded_arc; /* Last DALI arc level (0-254) commanded by daylight harvesting */
    bool is_group_master; /* TRUE when this sensor is the active controller of its cooperative harvesting group */
    uint32_t control_group; /* Effective control target: group/address the sensor maintains */
    uint32_t control_dali_line; /* Effective control target: DALI line mask the sensor controls */
    bool lux_seeded; /* FALSE while the harvest loop is awaiting its first real 304 reading after occupancy (last_lux / last_commanded_arc are still the previous occupancy's values until TRUE) */
    uint32_t light_setpoint; /* The DEVICE-resident daylight-harvest setpoint the loop actually regulates against (active profile). Lets the app draw the set-point line from the device, not its own config, so a device/app divergence is visible. */
    uint32_t group_mean_lux; /* The blended lux the harvest master regulates on (mean of active Leader members of this sensor's cooperative group). Equals last_lux for a standalone/Follower sensor. */
} SensorQuery;

/* The sensors' live state, a page of up to 20 at a time: send offset, read sensors and total_count, then ask for the next page. */
typedef struct _SensorsQuery {
    pb_size_t sensors_count;
    SensorQuery sensors[20]; /* A page of up to 20 SensorQuery entries starting at 'offset' (device holds 40; see nanopb max_count) */
    uint32_t offset; /* Request: absolute index of the first sensor to return (0-based; 0 = first page). Response: echoes the offset of this page so the client can place the entries at absolute slots. */
    uint32_t total_count; /* Response only: total number of sensors on the device. Lets the client page until offset + sensors.length >= total_count. Omitted (0) on older firmware, which returns every sensor in one page. */
} SensorsQuery;

/* List Step Structure for List Actions */
typedef struct _ListStepMessage {
    uint32_t step_index; /* Index of Step in List */
    TriggerMessage action; /* Action to perform */
    uint32_t time_seconds; /* Time in seconds between steps, uint16_t value */
} ListStepMessage;

/* Message to describe Scheduled Actions. Not sent natively, see AlarmMultiMessage */
typedef struct _AlarmMessage {
    uint32_t index; /* Alarm Index from 0 - 9 */
    bool enabled; /* Enabled Flag - FALSE (0) or TRUE (1) */
    TimeClockMessage start_time; /* Time to Start Action, or Astro Offset */
    TimeClockMessage end_time; /* Time to Stop Action, or Astro Offset */
    TriggerMessage start_trigger; /* Trigger Action to perform at start time */
    TriggerMessage end_trigger; /* Trigger Action to perform at end time */
    AlarmAstroType astro_start; /* Start Time Type */
    AlarmAstroType astro_end; /* End Time Type */
    AlarmRepeatType repeat; /* Alarm Repeat Type */
    uint32_t repeat_day_bitmask; /* 1 to trigger on this day. LSB (0) = Monday, MSB (6) = Sunday */
    uint32_t repeat_month_bitmask; /* 1 to trigger during this month. LSB (0) = January, MSB (11) = December */
    bool yearly; /* Should this Alarm happen each year? */
    bool start_offset_is_before; /* E.g. 10 minutes BEFORE or AFTER the start astro event? */
    bool end_offset_is_before; /* E.g. 10 minutes BEFORE or AFTER the end astro event? */
} AlarmMessage;

/* Message to describe the two Burn-In Actions. While Burn-In is active, the system will check associated DALI line and group and prevent any action other than 100% or 0%. Any value set over 1% will be forced to 100%. Not sent natively, see BurnInMultiMessage */
typedef struct _BurnInMessage {
    uint32_t index; /* Burn-in, 0-based */
    uint32_t line; /* DALI line mask the burn-in drives */
    uint32_t address; /* DALI address held at full while burning in (RECALL MAX LEVEL) */
    uint32_t query_address; /* DALI address queried to see whether the lights are on (the timer only runs while they are) */
    uint32_t time; /* Burn-in duration, minutes. Setting it restarts the countdown */
    uint32_t remaining; /* Minutes left (read only) */
    BurnInBitsMessage states; /* Its live state */
} BurnInMessage;

/* This message will allow an externally connected device to send a Trigger action */
typedef struct _ExternalTriggerMessage {
    TriggerMessage trigger; /* Can be used to action Triggers via the network instead of via a hardware input or on-board alarm */
} ExternalTriggerMessage;

/* Message used to send all Physical Inputs, for a specific profile */
typedef struct _InputMultiMessage {
    uint32_t profile; /* The profile these inputs belong to, 0-based */
    pb_size_t inputs_count;
    IOInputMessage inputs[24]; /* Every physical input, in index order */
} InputMultiMessage;

/* Message used to send all Outputs, for a specific profile */
typedef struct _OutputMultiMessage {
    uint32_t profile; /* The profile these outputs belong to, 0-based */
    pb_size_t outputs_count;
    IOOutputMessage outputs[8]; /* Every output, in index order */
} OutputMultiMessage;

/* Message used to send all DALI Inputs, for a specific profile */
typedef struct _DALIInputMultiMessage {
    uint32_t profile; /* The profile these DALI inputs belong to, 0-based */
    uint32_t input_index_offset; /* To support paginated results (0-9, 10-19, 20-29, 30-39) */
    pb_size_t inputs_count;
    DALIInputMessage inputs[10]; /* Every DALI input, in index order */
} DALIInputMultiMessage;

/* DEPRECATED */
typedef struct _IRMultiMessage {
    uint32_t profile; /* The profile these IR codes belong to, 0-based */
    pb_size_t irs_count;
    IOIRMessage irs[5]; /* Every IR slot, in index order */
} IRMultiMessage;

/* Message used to send a List. If more than 32 steps in the list, the ExtendedListMessage is used repeatedly to send the remainder. */
typedef struct _ListMessage {
    uint32_t list_index; /* Which list, 0-based */
    pb_size_t step_count;
    ListStepMessage step[32]; /* Limited to 32 for this Message Type; you must use ExtendedListMessage to configure more than 32 steps per List */
    uint32_t list_state; /* Typically will be 'DISABLED' to start with (requires a 'START LIST' trigger to begin) */
    uint32_t total_step_count; /* Can be greater than 32, but you must use ExtendedListMessage to send the rest */
} ListMessage;

/* This Message must be used when the List has more than 32 steps */
typedef struct _ExtendedListMessage {
    uint32_t list_index; /* Which List do these steps belong to? */
    uint32_t step_index_offset; /* 0 for the first ExtendedListMessage; offset by 32 for every ExtendedListMessage beyond the first */
    pb_size_t step_count;
    ListStepMessage step[32]; /* Up to 32 steps, from step_index_offset */
} ExtendedListMessage;

/* Message used to send the Alarms */
typedef struct _AlarmMultiMessage {
    pb_size_t alarm_count;
    AlarmMessage alarm[9]; /* Every alarm, in index order */
} AlarmMultiMessage;

/* Message used to send the Burn-Ins */
typedef struct _BurnInMultiMessage {
    pb_size_t burnin_count;
    BurnInMessage burnin[2]; /* Every burn-in, in index order */
} BurnInMultiMessage;

/* Defines a conditional logic rule that evaluates a condition and executes an action based on the result */
typedef struct _LogicMessage {
    uint32_t index; /* Index of this logic rule (0 to logic_count-1) */
    bool enabled; /* Whether this logic rule is active */
    TriggerMessage comparison_object; /* The source value to evaluate (e.g., DALI level, input state) */
    uint32_t comparison_value; /* The threshold/setpoint value to compare against */
    LogicComparisonType comparison_type; /* How to compare: equals, less than, greater than, etc. */
    TriggerMessage actionA; /* Action to execute if comparison evaluates to TRUE */
    TriggerMessage actionB; /* Action to execute if comparison evaluates to FALSE */
} LogicMessage;

/* Container for multiple logic rules (used when reading/writing all logic rules at once) */
typedef struct _LogicMultiMessage {
    pb_size_t logic_count;
    LogicMessage logic[5]; /* Array of logic rules (max logic_count entries) */
} LogicMultiMessage;

/* Message used to send specific sensor commands, such as Mute, Unmute and Override. Mute will stop the sensor from talking until; Unmute, Profile Change, or Program. Override will prevent the sensor from changing the currently selected level until it has timed-out */
typedef struct _SensorCommandMessage {
    uint32_t command; /* DEPRECATED: Use 'type' instead */
    uint32_t index; /* Which sensor, 0-based (INITIALISE ignores it: it is broadcast) */
    SensorCommandType type; /* What to do */
} SensorCommandMessage;

/* Message used to change Profiles. Note that changing the profile will cause the sensors to reset */
typedef struct _ChangeProfileMessage {
    uint32_t profile; /* The profile to make active, 0-based */
} ChangeProfileMessage;

/* Message used to show information on screen to aid with physical identification */
typedef struct _IdentifyMessage {
    uint64_t MAC; /* Not used: the device shows its own name, IP and MAC */
    uint64_t IP; /* Not used: the device shows its own name, IP and MAC */
} IdentifyMessage;

/* Message to update the device time. Message will be affected by Day Light Savings (If selected) and will refresh currently selected schedules */
typedef struct _UpdateTimeMessage {
    TimeClockMessage time; /* The new date and time (local time) */
} UpdateTimeMessage;

/* Message used to request device information, such as inputs, lists, sensors, etc */
typedef struct _ReadDeviceMessage {
    uint32_t profile; /* Profile to read, for INPUTS, DALI_INPUTS, OUTPUTS, IR and SENSOR */
    ReadType type; /* What to read - each ReadType says which payload comes back */
    uint32_t index; /* Which item, for SENSOR, LIST and LIST_EXTENDED */
    uint32_t secondary_index; /* For LIST_EXTENDED: which block of steps after the first 32 */
} ReadDeviceMessage;

/* Message used to send a secure login settings message. AES Encryption Required */
typedef struct _SecureDeviceSettingsMessage {
    char payload[1000]; /* Encrypted payload of a PB message. */
} SecureDeviceSettingsMessage;

/* DALI DTR Message structure. */
typedef struct _DTRPayloadMessage {
    pb_size_t dtr_count;
    uint8_t dtr[3]; /* For DALI, you can use 2 bytes, for eDALI 3. Format - DTR0 | DTR1 << 8 | DTR2 << 16 */
} DTRPayloadMessage;

/* Message to send a DALI command using various DALI frame types. */
typedef struct _DALIMessage {
    uint32_t line_mask; /* Binary mask; e.g. selecting line 1 out of 4 looks like 0b0001. For non queries, line_mask can contain multiple valid lines */
    uint32_t address; /* DALI Address */
    pb_size_t which_action;
    union {
        uint32_t frame_25_bit; /* Older eDALI commands are manufacturer specific, so we have to take a raw value. */
        uint32_t frame_25_bit_reply; /* Older eDALI commands can have a reply. */
        DALICommandType command; /* A standard DALI command (IEC 62386-102) to address. From DALI_TERMINATE (255) up the values are special commands, sent without an address; a value there that is not one is refused with INVALID_PARAMS (eDIDIO 1.6.3, ADDICT 3.9.3) */
        CustomDALICommandType custom_command; /* A command the device builds itself (arc level, fade, ...), with arg */
        DALIQueryType query; /* A standard DALI query to address; the reply is dali_query. Above DALI_QUERY_EXT_VERSION_NUMBER (255) the values are special queries, sent without an address; a value there that is not one is refused with INVALID_PARAMS (eDIDIO 1.6.3, ADDICT 3.9.3) */
        Type8CommandType type8; /* A DT8 colour command; the device sends ENABLE DEVICE TYPE 8 and the DTRs first */
        uint32_t frame_16_bit; /* Standard DALI Frame data - Don't use arg */
        uint32_t frame_16_bit_reply; /* Standard DALI Frame data with reply - Don't use arg */
        uint32_t frame_24_bit; /* Standard 24 Bit DALI Frame data - Don't use arg */
        uint32_t frame_24_bit_reply; /* Standard 24 Bit DALI Frame data with reply - Don't use arg */
        Type8QueryType type8_reply; /* A DT8 colour query; the reply is dali_query */
        DALI24DeviceSetting device24_setting; /* Settings for DALI 24 Bit Devices */
    } action;
    pb_size_t which_params;
    union {
        uint32_t arg; /* Context-dependent value: scene number (0-15), arc level (0-254), XY coordinates packed as (X << 16) | Y, or a special command's data byte as sent on the bus (INITIALISE: 0x00 all, 0xFF unaddressed, 0AAAAAA1 one device; SEARCHADDR H / M / L: the byte; PROGRAM / VERIFY SHORT ADDRESS: 0AAAAAA1, 0xFF to delete) */
        DTRPayloadMessage dtr; /* DTR0 / DTR1 / DTR2 values written before the command */
    } params;
    DALI24InstanceType instance_type; /* Instance for 24 bit device - Commands are sent via Type */
    DALI24OpCode op_code; /* OpCode for 24 bit device */
    bool send_twice; /* Should this command be sent twice on the DALI Line(s)? */
} DALIMessage;

/* Message reply for DALI Status Flag */
typedef struct _DALIStatusFlagMessage {
    pb_size_t flags_count;
    DALIStatusType flags[9]; /* The status bits that are set */
} DALIStatusFlagMessage;

/* DALI Response is tagged with the line and DALI address. */
typedef struct _DALIQueryResponse {
    pb_size_t which_payload;
    union {
        DALIStatusFlagMessage status_flags; /* Deprecated: the answer to QUERY STATUS as flags */
        PayloadMessage data; /* Deprecated: the answer byte in data.uint_data */
    } payload;
    /* New Query Method */
    DALIRXStatusFlag dali_flag;
    PayloadMessage response_data; /* The answer byte in response_data.uint_data, when dali_flag says one was received */
} DALIQueryResponse;

/* Message to invoke DALI Addressing */
typedef struct _DALIAddressingMessage {
    DALIAddressingType type; /* New or All */
    bool initialisation; /* First Address (TRUE) or Next Address (FALSE) */
    uint32_t line_mask; /* Line to Address - Must be singular */
    bool is24Bit; /* 24 Bit DALI (TRUE) or Standard (FALSE) */
    DALIAddressingError error; /* Response -> Error while Addressing */
    uint32_t index; /* Response -> Index of Set Address */
} DALIAddressingMessage;

/* Message to invoke DALI remapping */
typedef struct _DALIRemappingMessage {
    uint32_t from_address; /* DALI Address to change */
    uint32_t to_address; /* New address for device. If populated, this address will change to the from_address */
    uint32_t line_mask; /* Affected DALI Line */
    bool is24Bit; /* 24 bit DALI (TRUE) or Standard (FALSE) */
} DALIRemappingMessage;

/* A DALI device: its line and short address. */
typedef struct _DALIAddressableObject {
    uint32_t line; /* Which DALI Line is this Device on? */
    uint32_t address; /* What is the Short Address of this Device? */
} DALIAddressableObject;

/* Find DALI devices that may share a short address. Send line_mask (and is24Bit); the reply lists the suspects. */
typedef struct _DALIIdentifyDuplicatesMessage {
    uint32_t line_mask; /* Which DALI Line(s) to check */
    bool is24Bit; /* Use 24-bit DALI (DALI v2) or standard 16-bit DALI if FALSE */
    pb_size_t possible_duplicates_count;
    DALIAddressableObject possible_duplicates[128]; /* A collection of DALI Devices which *may* be using duplicated Short Addresses */
} DALIIdentifyDuplicatesMessage;

/* Message to send DMX on requested DMX line(s) */
typedef struct _DMXMessage {
    uint32_t zone; /* For Spektra (default of 0 is fine if not applicable) */
    uint32_t universe_mask; /* Which DMX Universes to apply the values to. Specified as a binary mask. Can be sent to multiple. */
    uint32_t channel; /* The actual channel number (not zero-based index) */
    uint32_t repeat; /* The number of times to repeat the data given (e.g. start from DMX channel 30 and set the RGB channel values (levels) of the next 3 lights, so repeat would be 3 with 3 levels provided) */
    pb_size_t level_count;
    uint8_t level[256]; /* The actual channel values/levels to send */
    uint32_t fade_time_by_10ms; /* The DMX Fade Task runs every 10ms, so a value of 25 will fade over 250ms */
} DMXMessage;

/* Message to send a DMX command with/without a response (Getset) */
typedef struct _RDMMessage {
    uint32_t universe_mask; /* Universe Mask - Must be a single universe. */
    uint64_t uid; /* UID of device to send the message to. Can be Multi/Broadcast */
    uint32_t pid; /* RDM PID - See Standard */
    uint32_t getset; /* Expects [DMX_RDM_GET_COMMAND = 0x20] or [DMX_RDM_SET_COMMAND = 0x30] */
    uint32_t datalength; /* Length of Data to send */
    pb_size_t data_count;
    uint8_t data[256]; /* Data */
} RDMMessage;

/* RDM Response message - source UID, PID, datalength and data */
typedef struct _RDMResponseMessage {
    uint64_t uid; /* UID of requested device */
    uint32_t pid; /* Message PID */
    uint32_t datalength; /* Length of Data to receive */
    pb_size_t data_count;
    uint8_t data[256]; /* Data */
} RDMResponseMessage;

/* RDM Discovery Message - Invokes Discovery with reply as RDMDiscoveryReplyMessage. isNext flag allows for more than 128 devices to be discovered in additional messages. */
typedef struct _RDMDiscoveryMessage {
    uint32_t universe_mask; /* Universe Mask - Must be a single universe */
    bool isNext; /* If true, RDM module will search for additional or 'next' 128 RDM devices. If false (empty), RDM module will re-init search for up to 128 devices */
} RDMDiscoveryMessage;

/* RDM Discovery Reply with up to 128 devices */
typedef struct _RDMDiscoveryReplyMessage {
    uint32_t discovery_count; /* How many UIDs were found in total */
    pb_size_t uid_count;
    uint64_t uid[128]; /* The RDM UIDs (48-bit) found, up to 128 per reply */
    uint32_t error_code; /* Non-zero if discovery failed */
} RDMDiscoveryReplyMessage;

/* Message for Spektra Setting Information */
typedef struct _SpektraSettingMessage {
    uint32_t zone; /* Determine Spektra zone from 0-9 */
    uint32_t start_address; /* DMX or DALI Start Address. Typically RED on the first fixture. */
    uint32_t line_or_universe_mask; /* Which DALI Line(s) or DMX Universe(s) to control */
    uint32_t protocol; /* E.g. DMX or DALI */
    uint32_t number_of_lights; /* Number of DALI or DMX fixtures connected. If more than available channels, the 'consecutive' option can be selected which will use multiple lines, starting from the first line specified above */
    uint32_t channels_per_light; /* E.g. 4 for RGBW */
    pb_size_t channel_colours_count;
    uint32_t channel_colours[256]; /* What colour is assigned to each channel (e.g. Red, Green, etc.) */
    SpektraUnscheduledBehaviourType unscheduled_behaviour; /* 0 = Random colours rotate sequence, 1 = Run default sequence (seq 1) */
    pb_size_t channel_mapping_count;
    uint32_t channel_mapping[10]; /* Channel mapping for DALI or future DMX virtual 'grouping' */
    LineAddressingType line_addressing; /* Independent or Consecutive */
    float zone_scale_factor; /* Zone Scale Factor - Float 0 to 1.0f */
} SpektraSettingMessage;

/* Spektra Colour Channel Config Structure */
typedef struct _SpektraColourConfigMessage {
    pb_size_t channel_value_count;
    uint32_t channel_value[10]; /* Include as many values as there are channels, e.g. [0, 255, 0] would be Green for an RGB light (3 channel values) */
} SpektraColourConfigMessage;

/* Spektra Sequence Configuration Message. Up to 144 sequences can be stored */
typedef struct _SpektraSequenceConfigMessage {
    uint32_t index; /* Index of sequence - 0 to 143 */
    uint32_t type; /* BLEND / SIMPLE CHASE / SHADOW CHASE / COMET / ROTATE / TWINKLE / BUILD-UP / CRASH / FIREWORKS */
    SpektraTransitionType transition; /* BLEND / SNAP / FADE_TO_BLACK */
    uint32_t fade_time_by_10ms; /* Correlates to blend transitions */
    uint32_t time_per_colour; /* How long each colour should be shown */
    uint32_t time_per_colour_unit; /* MILLISECONDS / SECONDS / MINUTES / HOURS */
    uint32_t time_per_step; /* How long each sequence type 'animation' takes (e.g. speed of the chase) */
    uint32_t time_per_step_unit; /* MILLISECONDS / SECONDS / MINUTES / HOURS */
    uint32_t range; /* Number of lights per repeating segment. 0 = no segmentation (all lights as one group). Values > 0 divide lights into groups of this size for pattern repetition */
    pb_size_t colour_count;
    uint64_t colour[20]; /* DEPRECATED - Use the 'colours' field (SpektraColourConfigMessage array) instead */
    uint32_t is_randomised_type; /* Will randomly select (from random_types_mask) one of the Sequence Types */
    uint32_t random_types_mask; /* A bitmask of Sequence Types */
    uint32_t is_reverse_direction; /* Animate the sequence in reverse light order */
    uint32_t is_cycle_direction; /* Animate the sequence in alternating light order from forward to reverse */
    char title[28]; /* The name of the Sequence */
    bool has_random_colour_order; /* Randomly pick the next colour out of the chosen colours */
    pb_size_t colours_count;
    SpektraColourConfigMessage colours[20]; /* The colours used in the Sequence */
    pb_size_t args_count;
    uint32_t args[5]; /* Function specific arguments * 5 */
} SpektraSequenceConfigMessage;

/* Message to define Spektra Calendar message. Zone options available in SpektraSettingsMessage to define what will happen if no action is scheduled on a calendar day. */
typedef struct _SpektraCalendarMessage {
    SpektraTargetType type; /* Spektra Type (e.g. Sequence or Theme) */
    uint32_t index; /* Index (i.e. which Sequence or Theme) */
    pb_size_t days_count;
    bool days[366]; /* Boolean array to specify when this Target Index is active (up to the number of days in a year) */
    bool isOverride; /* Boolean isOverride. If override, only run once */
} SpektraCalendarMessage;

/* Spektra Calendar Day Structure */
typedef struct _SpektraCalendarDayMessage {
    uint32_t day_index; /* Index of this day (0 to 365, 366 days total) */
    SpektraTargetType type; /* Spektra Type for this day (e.g. Sequence or Theme) */
    uint32_t target_index; /* Index of the specified Type (i.e. which Sequence or Theme) */
    bool isOverride; /* Boolean isOverride. If override, only run once */
} SpektraCalendarDayMessage;

/* Message to handle Spektra Calendar Read - This is the reply message to the read request */
typedef struct _SpektraCalendarOverviewMessage {
    uint32_t day_offset; /* Offset to start counting days from (0 is the first day of the year) */
    pb_size_t days_count;
    SpektraCalendarDayMessage days[90]; /* Schedule information for each day; supports up to 90 days per Message */
} SpektraCalendarOverviewMessage;

/* Message to define Spektra Theme. Up to 16 Themes */
typedef struct _SpektraThemeConfigMessage {
    uint32_t index; /* Theme slot, 0-based */
    pb_size_t colour_count;
    uint64_t colour[20]; /* DEPRECATED - Use the 'colours' field (SpektraColourConfigMessage array) instead */
    char title[28]; /* The name of the Theme */
    pb_size_t colours_count;
    SpektraColourConfigMessage colours[20]; /* The colours used in the Theme (will repeat colours if less colours than lights) */
} SpektraThemeConfigMessage;

/* Message to request Spektra Data */
typedef struct _SpektraReadMessage {
    SpektraTargetType type; /* What to read; with manifest set, SEQUENCE or THEME */
    uint32_t index; /* Slot index; when manifest = true, the manifest page number */
    bool manifest; /* TRUE = reply with a SpektraManifestMessage for 'type' instead of one slot. Additive: firmware below the manifest floor ignores this field and replies with slot 'index', so a client MUST gate on firmware version AND check that the reply actually carries spektra_manifest. */
} SpektraReadMessage;

/* Compact summary of which slots of a Spektra slot table hold data, and a change
 token for each. Reply to a SpektraReadMessage with manifest = true.

 Lets a client read only the slots that exist instead of polling every slot: a
 site with 8 sequences goes from 143 round trips to 1 + 8. That matters most on
 the transports where it hurts most - mobile/VPN links, and TLS.

 NOT an atomic snapshot: the device reads the slot table a sector at a time and
 releases its flash lock between sectors, so a write that lands mid-scan may or
 may not be reflected. That is correct for a change detector; do not treat the
 manifest as a transactional view. */
typedef struct _SpektraManifestMessage {
    SpektraTargetType type; /* SEQUENCE or THEME - which slot table this describes */
    uint32_t slot_offset; /* First slot index this page covers */
    uint32_t slot_count; /* Slots this page covers, occupied or not */
    bool is_last_page; /* TRUE on the final page of the table */
    pb_size_t index_count;
    uint32_t index[144]; /* Occupied slot indices, ascending */
    pb_size_t crc_count;
    uint32_t crc[144]; /* CRC-32 of each slot's stored page, aligned 1:1 with 'index'. Opaque change token: equal CRC means the stored bytes did not change. WIRE INVARIANT: index count == crc count; a receiver that sees otherwise must discard the message. */
} SpektraManifestMessage;

/* Message to control the Spektra Module */
typedef struct _SpektraControlMessage {
    SpektraTargetType type; /* Spektra Target Type - Sequence/Theme */
    uint32_t zone; /* Zone (0 to 9) or Zones (255) to control */
    uint32_t index; /* Index of Action. I.e. Sequence 5 */
    SpektraActionType action; /* Type of Action. Start/Resume/Stop */
} SpektraControlMessage;

/* What Spektra is doing right now, one entry per zone in every repeated field: the reply to spektra_read LIVE. */
typedef struct _SpektraLiveMessage {
    pb_size_t type_count;
    SpektraTargetType type[10]; /* Target Type Per Zone (Sequence/Theme etc) */
    pb_size_t index_count;
    uint32_t index[10]; /* Target Index Per Zone */
    pb_size_t action_count;
    SpektraActionType action[10]; /* Target Action Per Zone */
    pb_size_t step_index_count;
    uint32_t step_index[10]; /* Current Step */
    pb_size_t step_index_direction_count;
    uint32_t step_index_direction[10]; /* Forwards/Backwards (If Cycling) */
    pb_size_t colour_index_count;
    uint32_t colour_index[10]; /* Current State of Colour Index (Changes over time) */
    pb_size_t colour_range_count;
    uint32_t colour_range[10]; /* Current State of Colour Range (Changes based on Sequence Step) */
    pb_size_t random_seq_type_count;
    uint32_t random_seq_type[10]; /* Currently Active Random Sequence Type */
    pb_size_t zone_active_count;
    bool zone_active[10]; /* Flag to show if any channel in this zone is active */
} SpektraLiveMessage;

/* Structure to describe the DMX to DALI translation */
typedef struct _DMXTranslationObject {
    uint32_t line_in; /* DMX IN - Must configure line as DMX IN */
    uint32_t line_out; /* DALI OUT */
    uint32_t dmx_start_address; /* DMX Start Address */
    uint32_t channel_count; /* DMX Count */
    pb_size_t dali_array_count;
    uint8_t dali_array[64]; /* DALI Addresses */
    uint32_t affected_input; /* Bitmask of affected inputs */
    bool blocking; /* If TRUE (1), the inputs will be ignored if the internal DMX receiving flag is TRUE */
    bool enabled; /* Translation object is enabled (1) or disabled (0) */
    uint32_t index; /* Index of Translation Object */
} DMXTranslationObject;

/* Message to describe the DMX to DALI translation objects. For a 4 line controller, up to 3 objects can be created allowing for single/multi line translation to single/multi line out. */
typedef struct _DMXProtocolTranslation {
    pb_size_t object_count;
    DMXTranslationObject object[3]; /* Typically 1 for a 4 Pole device but can be more for 9 Pole eDIDIO */
} DMXProtocolTranslation;

/* Structure of Input state mask when InputStateResponse message is sent. 1 is HIGH, 0 is LOW. GPIO are configured as default HIGH. If not connected, a momentary input will return TRUE (1) */
typedef struct _InputStateMessage {
    bool use_mask; /* Reply with a mask rather than a list of active inputs. */
} InputStateMessage;

/* Message containing the InputStateMessage mask */
typedef struct _InputStateResponse {
    pb_size_t inputs_count;
    uint8_t inputs[24]; /* Contains Inputs that are Low (i.e. currently active) */
    uint32_t input_mask; /* Usage is determined by "InputStateMessage: use_mask" */
} InputStateResponse;

/* Message that contains DALI polled levels. Levels are split into pages of 64 values */
typedef struct _LevelCacheResponse { /* DALI/DMX agnostic. */
    pb_size_t levels_count;
    uint8_t levels[64]; /* Repeated Level array */
    uint32_t line; /* Requested Line */
    uint32_t page; /* Page of requested information */
} LevelCacheResponse;

/* User-defined names for profiles (max profile_count entries) */
typedef struct _ProfileAliases {
    pb_size_t profiles_count;
    char profiles[6][23]; /* One name per profile, in index order */
} ProfileAliases;

/* User-defined names for physical inputs (max input_count entries) */
typedef struct _InputAliases {
    pb_size_t inputs_count;
    char inputs[24][23]; /* One name per physical input, in index order */
} InputAliases;

/* User-defined names for physical outputs (max output_count entries) */
typedef struct _OutputAliases {
    pb_size_t outputs_count;
    char outputs[8][23]; /* One name per output, in index order */
} OutputAliases;

/* User-defined names for lists (max list_count entries) */
typedef struct _ListAliases {
    pb_size_t lists_count;
    char lists[32][23]; /* One name per list, in index order */
} ListAliases;

/* User-defined names for sensors (max 40 entries) */
typedef struct _SensorAliases {
    pb_size_t sensors_count;
    char sensors[40][23]; /* One name per sensor, in index order */
} SensorAliases;

/* User-defined names for DALI input devices (max input_dali_count entries) */
typedef struct _DaliInputAliases {
    pb_size_t dali_inputs_count;
    char dali_inputs[40][23]; /* One name per DALI input, in index order */
} DaliInputAliases;

/* User-defined names for schedules/alarms (max alarm_count entries) */
typedef struct _ScheduleAliases {
    pb_size_t schedules_count;
    char schedules[10][23]; /* One name per alarm (schedule), in index order */
} ScheduleAliases;

/* Container for getting or setting user-defined aliases. Only one alias type can be sent per message. */
typedef struct _DataAliases {
    AliasCommandType command; /* GET_ALIASES to read, SET_ALIASES to write */
    pb_size_t which_aliases;
    union {
        ProfileAliases profiles; /* Profile names */
        InputAliases inputs; /* Physical input names */
        OutputAliases outputs; /* Output names */
        ListAliases lists; /* List names */
        SensorAliases sensors; /* Sensor names */
        DaliInputAliases dali_inputs; /* DALI input names */
        ScheduleAliases schedules; /* Alarm (schedule) names */
    } aliases;
} DataAliases;

/* Message to request system information. Contains vital information about connected devices configuration capabilities, as well as firmware and hardware version. */
typedef struct _DiagnosticSystemInfoResponse {
    char firmware[16]; /* Firmware Version number */
    char hardware[64]; /* Hardware Version number */
    char error[16]; /* Any populated Error message */
    uint8_t input_count; /* Number of supported Inputs */
    uint8_t output_count; /* Number of supported Outputs */
    uint8_t ir_count; /* Number of supported IR codes */
    uint8_t list_step_count; /* Number of supported List Steps */
    uint8_t list_count; /* Number of supported Lists */
    uint8_t alarm_count; /* Number of supported Alarms (Schedules) */
    uint8_t burnin_count; /* Number of supported Burn-ins */
    uint8_t spektra_seq_count; /* Number of supported Spektra Sequences */
    uint8_t spektra_seq_step_count; /* Number of supported Spektra Sequence Steps */
    uint8_t spektra_theme_count; /* Number of supported Spektra Themes */
    uint8_t spektra_static_count; /* Number of supported Spektra Static Colours */
    uint32_t proto_version; /* Protocol version = ProtocolVersion_PROTOCOL_VERSION_CURRENT, byte-packed 0x00_MM_mm_PP (e.g. 0x010301 = 1.3.1) */
    uint8_t line_count; /* Number of supported Control Lines (for DMX, DALI) */
    pb_size_t lines_count;
    LineType lines[4]; /* Denotes what control type is assigned to each line (e.g. DMX, DALI) */
    uint32_t profile_count; /* Number of supported Profiles */
    uint32_t preset_code_count; /* Number of supported Preset Codes */
    uint32_t user_level_count; /* Number of supported User Levels */
    uint32_t dmx_to_dali_count; /* Number of supported DMX to DALI Translations */
    uint32_t spektra_zone_count; /* Number of supported Spektra Zones */
    uint32_t logic_count; /* Number of supported Logic Mappings */
    uint32_t input_dali_count; /* Number of supported DALI Inputs */
    char vendor_id[16]; /* Vendor ID - "Control Freak" */
    uint32_t selected_profile; /* Currently Selected Profile */
    char bootloader[16]; /* Bootloader Version number (if applicable) */
    char commit_hash[48]; /* Git commit hash from the build system */
    char build_date[24]; /* Build date/time string (e.g. "Apr  8 2026 14:30:00") */
    bool has_confidentiality_key; /* TRUE if the device can accept an encrypted (V3) firmware image. Lets the updater gate the V3 option. Older firmware omits it -> decodes as false. */
} DiagnosticSystemInfoResponse;

/* Request a diagnostic response message of a given type. */
typedef struct _DiagnosticMessage {
    DiagnosticMessageType type; /* Which report; each DiagnosticMessageType says what comes back */
    uint32_t page; /* Allow paging of results, eg. 32 DMX levels per page, 16 pages. */
    uint32_t line; /* If a line/DMX universe needs to be indicated it can go here. */
} DiagnosticMessage;

