    char project_name[32]; /* For project documentation */
    float longitude; /* For astronomical calculations (e.g. sunrise/sunset) */
    float latitude; /* For astronomical calculations (e.g. sunrise/sunset) */
    float local_offset; /* For astronomical calculations (e.g. sunrise/sunset) */
    bool daylight_savings; /* For astronomical calculations (e.g. sunrise/sunset) */
